\label{assumption_cfl} 
We will assume the following CFL conditions.
\begin{align*}
     \Delta t\lesssim h^2, \text{ and } N_t = \frac{T}{\Delta t}\gtrsim  h^{-2}.
\end{align*}
To the diffusion update is nonexpansive in the standard mass norm (defined in Section \ref{sec_norms}) $\|(I-\Delta tM^{-1}S)a\|_M\le \|a\|_M, a\in\mathbb R^N$, we will enforce $ \Delta t\lambda_{\max}(M^{-1}S)\le 2$. 
\textcolor{black}{Using the inverse inequality, it follows that $ \lambda_{\max}(M^{-1}S)\le C h^{-2}.$}
A derivation is introduced in the Appendix \ref{section_cfl_appendix} for the completeness of the manuscript.
For the network complexity estimates below, we additionally
choose $\Delta t\sim h^2$ subject to
Assumption~\ref{assumption_cfl}, so that $N_t\sim h^{-2}$.

The formula $L_h=I+\Delta t I-\Delta t M^{-1}S$ contains the linear reaction contribution coming from the $+v$ part of $v-v^2$.  If the quadrature is not mass-exact, then the quadrature approximation of the linear reaction vector is $M_Qu$, not $Mu$.  The quadrature-based KPP update would then be
\begin{align*}
     u_h^{n+1}
 =
 \left(I-\Delta t M^{-1}S+\Delta t M^{-1}M_Q\right)u_h^n
 -
 \Delta t M^{-1}B^TW(Bu_h^n)^{\odot2}.
\end{align*}
Equivalently, the difference $\Delta t M^{-1}(M_Q-M)u_h^n$ would be an additional quadrature consistency term.  In the rest of this note we do not pursue this case; we assume degree-$3r$ exact quadrature, so $M_Q=M$ and $q_Q=q$.

\label{assumption_reference_bounded}
There exists $M_*>0$, independent of $h$, $\Delta t$, $n$, $\delta$, and the initial condition in the admissible class, such that the reference fully discrete solution satisfies
\begin{align*}
     \left\lvert (Bu_h^n)_q \right\rvert\le M_*,
 q=1,\dots,Q,
 n=0,\dots,N_t.
\end{align*}
We choose a clipping level $M_0\ge M_*$, where $M_0$ is independent of the $h, \Delta t$ and initial condtion.

\label{def_network_predicted_traj}
    Let $\tilde{R}_\delta$ be the scalar square network from Lemma~\ref{lemma_yarotsky_product} with $\delta$ accuracy with domain $[-M_0, M_0]$.
Define the network-implemented coefficient $u_{h, \delta}^n\in\mathbb{R}^{N}$ by
\begin{align*}
     u_{h,\delta}^{n+1}=L_hu_{h,\delta}^n+C_h{R}_\delta(Bu_{h,\delta}^n), \text{ where } R_{\delta} = \tilde{R}_{\delta}\circ \chi_{M_0}.
\end{align*}
Here $\chi_{M_0}$ is the clipping operator implemented by ReLU, $\tilde{R}_{\delta}$ is applied to $\chi_{M_0} (Bu_{h, \delta}^n)$ entry-wise, and  initial finite element encoding ($n = 0$) is the same as as the reference scheme $ u_{h,\delta}^0=u_h^0.$
We then call the associated finite element function  $v_{h,\delta}^n(x):=\sum_{j=1}^N (u_{h,\delta}^n)_j\phi_j(x)$ semi-network approximation.
Define the coefficient error $ e^n:=u_h^n-u_{h,\delta}^n.$

\label{lem:recursion}
Let $u_{h, \delta}^n$, $e^n$ and network $R_\delta$ be defined as in Definition \ref{def_network_predicted_traj}.
Assume the boundedness Assumption~\ref{assumption_reference_bounded} and let $M_0\ge M_*$.  Then,
\begin{align*}
     \left\lVert e^{n+1} \right\rVert_M
 \le
 \left(\left\lVert L_h \right\rVert_{M\to M}+2M_0\left\lVert C_h \right\rVert_{W\to M}\left\lVert B \right\rVert_{M\to W}\right)\left\lVert e^n \right\rVert_M
 +
 \left\lVert C_h \right\rVert_{W\to M}\sqrt{\operatorname{tr}(W)}\,\delta.
\end{align*}

\label{prop_accumulative_error}
Assume Assumption \ref{assumption_quadrature} (quadrature) and the exact-quadrature consequences \eqref{eq:kpp-exact-quadrature-consequences}, Assumption \ref{assumption_cfl} (CFL), Assumption~\ref{assumption_reference_bounded} (numerical bounded).
Let the predicted trajectory $u_{h, \delta}^n$, semi-network approximation $v_{h, \delta}^n$, error $e^n$ and network $R_{\delta}$ be defined as in the Definition \ref{def_network_predicted_traj}.
Then there exists a constant $C_T>0$ depending on $T$, independent of $\delta, \Delta t$, such that
\begin{align*}
     \left\lVert v_h^{N_t}-v_{h,\delta}^{N_t} \right\rVert_{L^2(\Omega)} = \left\lVert e^{N_t} \right\rVert_M\le C_T\delta.
\end{align*}

\label{assumption_fem_p1}
Let $\mathcal{A}$ be a class of admissible initial data.  We assume the following.
\begin{enumerate}
\item $P_1$ finite element setting.
The spaces $V_h\subset H_0^1(\Omega)$ are continuous $P_1$ Lagrange finite element spaces on affine, shape-regular, quasi-uniform  and locally convex simplicial meshes.  
Thus each basis function $\phi_j$ is continuous and piecewise affine, and the number of degrees of freedom satisfies $N\sim h^{-d}$.


\item Initial-data encoding.
There is a fixed finite element encoder $\mathcal{E}_h:\mathcal{A}\to\mathbb{R}^N$, for example nodal interpolation or $L^2$-projection, and both the numerical scheme and the network scheme start from $ u_h^0=u_{h,\delta}^0=\mathcal{E}_h(v_0).$
\end{enumerate}

\label{lemma_fem_properties}
Under Assumption~\ref{assumption_fem_mesh_nonlocal}, there exist constants
$c_M,C_M,c_D,C_D,C_{\mathrm{loc}}>0$, independent of $h$, $j$ such that
\begin{align*}
    N\sim h^{-d},
\quad
c_Mh^d\|a\|_2^2
\le a^TMa
\le C_Mh^d\|a\|_2^2,
\quad\text{for all }a\in\mathbb R^N.
\end{align*}

For each nodal Lagrange basis function $\phi_j$, there exists a closed axis-aligned box
\begin{align*}
    \omega_{j,h}:=\operatorname{int}(\operatorname{supp}\phi_j)
\subset D_{j,h}
=
\prod_{i=1}^d[a_{j,i},b_{j,i}]
\end{align*}
such that $c_Dh\le b_{j,i}-a_{j,i}\le C_Dh, i=1, ... ,d,$
and $\sup_{x\in\mathbb R^d}
|\{j:x\in D_{j,h}\}|
\le C_{\mathrm{loc}}.$

\label{lemma_support_preserving_approximation}
Let $ D=\prod_{i=1}^d[a_i,b_i]\subset\mathbb R^d$
be a closed box with nonempty interior, and let $n\geq1$ be an integer.
Suppose that $f\in W^{n,\infty}(\mathbb R^d)$ and
$\operatorname{supp}(f)\subseteq D$.  
Then for any $0<\varepsilon<1$, there exists a scaler $C_f>0$, depending on $D$, $d$, $n$ and an upper bound for $\|f\|_{W^{n,\infty}(\mathbb R^d)}$, 
ReLU networks $\widetilde f_\varepsilon:\mathbb R^d\to\mathbb R$ such that
\begin{align*}
 \left\lVert f-\widetilde f_\varepsilon \right\rVert_{L^\infty(\mathbb R^d)}
 \leq \varepsilon, \text{ and }
 \operatorname{supp}(\widetilde f_\varepsilon)\subseteq D.
\end{align*}
Moreover, the network can be chosen with same size as usual,
\begin{align*}
 \operatorname{depth}(\widetilde f_\varepsilon)
 &\lesssim C_f\bigl(1+\log(1/\varepsilon)\bigr),\\
 \operatorname{width}(\widetilde f_\varepsilon)
 &\lesssim \varepsilon^{-d/n},\\
 \operatorname{size}(\widetilde f_\varepsilon)
 &\lesssim
 C_f\varepsilon^{-d/n}\bigl(1+\log(1/\varepsilon)\bigr).
\end{align*}
Here size is the number of nonzero affine weights.
